// components/VideoImage.js
import React, { useState, useEffect } from 'react';

// 简单的SVG占位图（base64编码）
const PLACEHOLDER_SVG = 'data:image/svg+xml;base64,';

const VideoImage = ({ src, alt, className = '' }) => {
  // 验证URL是否有效
  const isValidUrl = (url) => {
    if (!url || url.trim() === '') return false;
    try {
      // 检查是否是有效的URL格式
      if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('//')) {
        return true;
      }
      // 相对路径也认为是有效的
      if (url.startsWith('/')) {
        return true;
      }
      return false;
    } catch (e) {
      return false;
    }
  };

  // 初始化状态：如果src有效则使用src，否则使用占位图
  const [imgSrc, setImgSrc] = useState(() => {
    if (src && isValidUrl(src)) {
      return src;
    }
    return PLACEHOLDER_SVG;
  });
  const [isLoading, setIsLoading] = useState(() => {
    return src && isValidUrl(src);
  });
  const [hasError, setHasError] = useState(() => {
    return !src || !isValidUrl(src);
  });
  const [retryCount, setRetryCount] = useState(0);

  const handleError = (e) => {
    console.warn('图片加载失败:', imgSrc, '重试次数:', retryCount);

    // 如果还没重试过，且原始URL有效，尝试重新加载
    if (retryCount < 1 && isValidUrl(src) && imgSrc === src) {
      setRetryCount(prev => prev + 1);
      // 延迟后重试，可能是网络问题
      setTimeout(() => {
        setImgSrc(src + (src.includes('?') ? '&' : '?') + '_retry=' + Date.now());
        setIsLoading(true);
      }, 500);
      return;
    }

    // 如果重试失败或URL无效，使用占位图
    if (imgSrc !== PLACEHOLDER_SVG) {
      setImgSrc(PLACEHOLDER_SVG);
      setHasError(true);
    }
    setIsLoading(false);
  };

  const handleLoad = () => {
    setIsLoading(false);
    setHasError(false);
    setRetryCount(0);
  };

  // 如果src变化，重置状态
  useEffect(() => {
    if (src && isValidUrl(src)) {
      // 当src变化时，总是更新（即使当前是占位图）
      if (imgSrc !== src) {
        setImgSrc(src);
        setIsLoading(true);
        setHasError(false);
        setRetryCount(0);
      }
    } else {
      // 如果src无效或为空，使用占位图
      if (imgSrc !== PLACEHOLDER_SVG) {
        setImgSrc(PLACEHOLDER_SVG);
        setIsLoading(false);
        setHasError(true);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [src]);

  const finalSrc = isValidUrl(imgSrc) ? imgSrc : PLACEHOLDER_SVG;

  // 调试日志
  useEffect(() => {
    if (src) {
      console.log('VideoImage - src:', src, 'imgSrc:', imgSrc, 'finalSrc:', finalSrc, 'isValidUrl:', isValidUrl(src));
    }
  }, [src, imgSrc, finalSrc]);

  return (
    <div className={`video-image-wrapper ${className}`} style={{ position: 'relative', width: '100%', height: '100%', overflow: 'hidden' }}>
      {isLoading && !hasError && (
        <div 
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            backgroundColor: '#f0f0f0',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#999',
            fontSize: '12px',
            zIndex: 1
          }}
        >
          加载中...
        </div>
      )}
      <img
        src={finalSrc}
        alt={alt || '视频封面'}
        className={className}
        onError={handleError}
        onLoad={handleLoad}
        style={{
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          objectPosition: 'center',
          display: 'block',
          backgroundColor: '#f0f0f0',
          position: 'relative',
          zIndex: 0,
          imageRendering: 'auto',
          WebkitImageRendering: '-webkit-optimize-contrast',
          msInterpolationMode: 'bicubic',
          transform: 'translateZ(0)',
          WebkitTransform: 'translateZ(0)',
          willChange: 'transform',
          WebkitBackfaceVisibility: 'hidden',
          backfaceVisibility: 'hidden'
        }}
        loading={className.includes('video-poster-image') ? 'eager' : 'lazy'}
        decoding="sync"
        crossOrigin="anonymous"
        referrerPolicy="no-referrer"
      />
    </div>
  );
};

export default VideoImage;
